/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    Args                locArgs;
    common              locCommon;

    FormWindowControl   locFormImageControl;
    FormStringControl   locFormStringControl;
    FormGroupControl    locFormGroupControl;

    AVAQRCodeString     locQRCodeString;
    AVAQRCodeContainer  locQRCodeContainer;
    Image               locQRCodeImage;

    SalesTable          locSalesTable;
    ProdTable           locProdTable;
    ProdRouteJob        locProdRouteJob;

    locArgs = this.args();

    super();

    locFormImageControl  = QRCodeImage;
    locFormStringControl = QRCodeString;
    locFormGroupControl  = QRCodeInfoGroup;

    if(     locArgs 
        &&  locArgs.record().RecId)
    {
        locCommon = locArgs.record();

        switch(locCommon.TableId)
        {
            case tableNum(SalesTable):
                locSalesTable   = locCommon;
                locQRCodeString = locSalesTable.SalesId;
                QRCodeString.label("@SYS9694");
                break;

            case tableNum(ProdTable):
                locProdTable    = locCommon;
                locQRCodeString = locProdTable.ProdId;

                if(locArgs.caller().name() == formStr(ProdTableOverview))
                {
                    if(locArgs.menuItemType() == MenuItemType::Display)
                    {
                        if(locArgs.menuItemName() == menuItemDisplayStr(AVAQRCodeDisplay_ProdTable_Batch))
                        {
                            QRCodeString.label("@PRO90");
                        }
                        else if(locArgs.menuItemName() == menuItemDisplayStr(AVAQRCodeDisplay_ProdTable_Prod))
                        {
                            QRCodeString.label("@SYS4398");
                        }
                        else
                        {
                            QRCodeString.label("@SYS4398");
                        }
                    }
                }
                else
                {
                    QRCodeString.label("@SYS4398");
                }
                break;

            case tableNum(ProdRouteJob):
                if(locArgs.caller().name() == formStr(ProdTableOverview))
                {
                    if(locArgs.menuItemType() == MenuItemType::Display)
                    {
                        locProdRouteJob = locCommon;
                        locQRCodeString = locProdRouteJob.JobId;

                        if(locArgs.menuItemName() == menuItemDisplayStr(AVAQRCodeDisplay_ProdRouteJob))
                        {
                            QRCodeString.label("@SYS22890");
                        }
                        else
                        {
                            QRCodeString.label("@SYS22890");
                        }
                    }
                }
                break;


        }
    }

    if(locArgs && locArgs.parm())
    {
        locQRCodeString = locArgs.parm();
        //QRCodeString.label("@NDX:NXAQRCodeString");
    }

    if(locQRCodeString)
    {
        locQRCodeContainer = AVAHelperClass::generateQRCode(locQRCodeString);
        if(locQRCodeContainer != conNull())
        {
            locQRCodeImage = AVAHelperClass::generateQRCodeImage(locQRCodeContainer);
        }
        locFormImageControl.image(locQRCodeImage);
        locFormStringControl.text(locQRCodeString);
    }
    locFormGroupControl.setFocus();
    locFormStringControl.setFocus();
}

/// <summary>
///     AVA <c>clicked</c> method.
/// </summary>
public void clicked()
{
    super();

    this.formRun().closeOk();
}
